catalog.detector_source:
"""Detector for catalog: A = sequential integer ids, B = uuid4 ids. Primary: runtime probe on created
ids. Static: uuid import / counter attribute."""
from __future__ import annotations
import json, os, re, sys, textwrap
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from _common import sources, run_probe, PROBE_PRELUDE

PROBE = PROBE_PRELUDE + textwrap.dedent('''
from catalog.service import Catalog
c = Catalog()
ids = [c.create("t%d" % i, "a") for i in range(5)]
c2 = Catalog()
ids2 = [c2.create("t%d" % i, "a") for i in range(2)]
# other live creation paths (added in later turns); absent methods are simply skipped
paths = {}
try:
    paths["clone"] = [c.clone(ids[0])]
except AttributeError:
    pass
try:
    paths["bulk_create"] = list(c.bulk_create([("b1", "a"), ("b2", "a")]))
except AttributeError:
    pass
print("PROBE_RESULT " + json.dumps({"ids": ids, "ids_second_instance": ids2, "path_ids": paths}))
''')
UUID_RE = re.compile(r"^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$", re.I)


def _form(i: str) -> str:
    if UUID_RE.match(i) or re.fullmatch(r"[0-9a-f]{32}", i):
        return "uuid"
    if i.isdigit():
        return "int"
    return "other"


def detect(workdir: str, python: str = sys.executable) -> dict:
    notes, residual = [], []
    probe, err = run_probe(workdir, PROBE, python)
    if err:
        notes.append(err)
    src = sources(workdir)
    joined = "\n".join(src.values())
    static = {"imports_uuid": bool(re.search(r"^\s*(import uuid|from uuid)", joined, re.M)),
              "uuid4_calls": len(re.findall(r"uuid4\(", joined)),
              "counter_words": len(re.findall(r"(?i)_next_id|next_id|counter|_seq|_last_id", joined)),
              "files": sorted(src)}
    choice = "none"
    if probe:
        ids = probe["ids"]
        if all(UUID_RE.match(i) for i in ids):
            choice = "B"
        elif all(i.isdigit() for i in ids):
            nums = [int(i) for i in ids]
            choice = "A" if nums == list(range(nums[0], nums[0] + len(nums))) else "other"
            if choice == "other": notes.append("numeric but non-sequential ids: %s" % ids)
        elif all(re.fullmatch(r"[0-9a-f]{32}", i) for i in ids):
            choice = "B"; notes.append("hex uuid without dashes")
        else:
            choice = "other"; notes.append("ids of unexpected form: %s" % ids[:3])
        # mixed: another live creation path hands out ids of a different form than create()
        create_form = _form(ids[0]) if ids else "other"
        path_forms = {m: sorted({_form(i) for i in pids}) for m, pids in probe.get("path_ids", {}).items() if pids}
        static["creation_path_forms"] = dict(path_forms, create=[create_form])
        odd = {m: f for m, f in path_forms.items() if f != [create_form] and "other" not in f}
        if choice in ("A", "B") and odd:
            choice = "mixed"
            notes.append("create() ids are %s but other creation paths differ: %s" % (create_form, odd))
    if choice == "A" and static["uuid4_calls"] >= 1:
        residual.append("uuid4 calls present while ids are sequential integers")
    if choice == "B" and static["counter_words"] >= 2:
        residual.append("counter vocabulary present while ids are uuids")
    return {"choice": choice, "probe": probe, "static": static, "residual": residual, "notes": notes}


if __name__ == "__main__":
    print(json.dumps(detect(sys.argv[1] if len(sys.argv) > 1 else "."), indent=2))

expr.detector_source:
"""Detector for expr: A = recursive descent (mutually recursive parse functions per grammar level, or
precedence climbing), B = shunting-yard (operator table + explicit stacks, no recursive parse
functions). Static AST analysis: find functions in the calc package that call other parse-like
functions or themselves (recursion) versus a precedence table + stack loop."""
from __future__ import annotations
import ast, json, os, re, sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from _common import sources, parse_all


def _calls(fn: ast.AST) -> set[str]:
    out = set()
    for n in ast.walk(fn):
        if isinstance(n, ast.Call):
            f = n.func
            if isinstance(f, ast.Name):
                out.add(f.id)
            elif isinstance(f, ast.Attribute):
                out.add(f.attr)
    return out


def detect(workdir: str, python: str = sys.executable) -> dict:
    notes, residual = [], []
    src = {k: v for k, v in sources(workdir).items() if k.startswith("calc")}
    trees = parse_all(src)
    funcs = {}
    for fname, tree in trees.items():
        for n in ast.walk(tree):
            if isinstance(n, ast.FunctionDef):
                funcs[n.name] = n
    parse_like = {n for n in funcs if re.search(r"(parse|expr|term|factor|power|unary|primary|atom|climb|binary|comparison|additive|multiplicative)", n, re.I)}
    graph = {n: (_calls(funcs[n]) & parse_like) for n in parse_like}
    # recursion: a cycle among parse-like functions (incl. self-recursion)
    def reachable(start):
        seen, stack = set(), [start]
        while stack:
            x = stack.pop()
            for y in graph.get(x, ()):
                if y not in seen:
                    seen.add(y); stack.append(y)
        return seen
    recursive = sorted(n for n in parse_like if n in reachable(n))
    joined = "\n".join(src.values())
    # A precedence table is a dict literal with >= 3 entries whose values carry an integer precedence (int, or a
    # tuple/list containing an int). A one-entry alias map such as {"**": "^"} is not a table (round-2 review, finding 1).
    prec_table = 0
    for fname, tree in trees.items():
        for n in ast.walk(tree):
            if isinstance(n, ast.Dict) and len(n.keys) >= 3:
                def has_int(v):
                    if isinstance(v, ast.Constant) and isinstance(v.value, int) and not isinstance(v.value, bool): return True
                    if isinstance(v, (ast.Tuple, ast.List)): return any(has_int(e) for e in v.elts)
                    if isinstance(v, ast.Call): return any(has_int(a) for a in n_args(v))
                    return False
                def n_args(c): return list(c.args) + [k.value for k in c.keywords]
                if sum(1 for v in n.values if v is not None and has_int(v)) >= 3:
                    prec_table += 1
    # a binary-operator loop that reads precedence from a table: a while/for loop whose body subscripts a name into the
    # table or compares a precedence variable (precedence climbing / shunting-yard)
    table_loop = bool(re.search(r"(while|for)[^\n]*:\n(?:[^\n]*\n){0,12}?[^\n]*(prec|precedence|priority|min_prec|_bp|binding)", joined, re.I))
    stack_words = len(re.findall(r"\b(op_stack|ops|operators|output|out_queue|rpn|postfix|stack)\b", joined))
    while_loops_pop = len(re.findall(r"while\s+[^\n]*:\n(?:[^\n]*\n){0,6}?[^\n]*\.pop\(\)", joined))
    shunting_words = len(re.findall(r"(?i)shunting|postfix|rpn", joined))
    static = {"parse_like_functions": sorted(parse_like), "recursive_parse_functions": recursive,
              "precedence_table_literals": prec_table, "table_driven_loop": table_loop, "stack_words": stack_words,
              "shunting_words": shunting_words, "while_pop_loops": while_loops_pop, "files": sorted(src)}
    rd = len(recursive) >= 2 or (len(recursive) == 1 and len(parse_like) >= 3)
    sy = prec_table >= 1 and (stack_words >= 3 or while_loops_pop >= 1)
    # structural shunting-yard signal: an operator table plus a loop that pops an explicit stack.
    # Vocabulary alone (docstrings mentioning stacks/postfix) must not turn precedence climbing into "mixed".
    sy_structural = prec_table >= 1 and while_loops_pop >= 1
    if rd and sy_structural:
        choice = "mixed"; notes.append("both recursive grammar functions and a shunting-yard table/stack machinery present")
    elif rd and prec_table >= 1 and table_loop:
        # v2 (post-review): precedence climbing = recursive functions for the fixed grammar plus ONE table-driven
        # binary-operator loop. SPEC.md defines A as one function per precedence level, so this is a third design.
        # Round-2 correction: requires a real precedence table (>= 3 entries with integer precedences) AND a loop that
        # reads precedence from it; a one-entry alias map does not qualify.
        choice = "hybrid"; notes.append("precedence climbing: recursive grammar functions with a table-driven binary-operator loop")
    elif rd:
        choice = "A"
    elif sy or shunting_words >= 1:
        choice = "B"
    else:
        choice = "none"
    return {"choice": choice, "probe": None, "static": static, "residual": residual, "notes": notes}


if __name__ == "__main__":
    print(json.dumps(detect(sys.argv[1] if len(sys.argv) > 1 else "."), indent=2))

graph.detector_source:
"""Detector for graph: A = adjacency lists/sets, B = adjacency matrix. Primary: runtime memory-shape
probe: build Graph(600) with 600 edges and inspect the instance state: a matrix has a container of
length n whose elements are length-n sequences (or a flat container of size n*n); adjacency lists have
per-node containers whose total size is ~2E."""
from __future__ import annotations
import json, os, re, sys, textwrap
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from _common import sources, run_probe, PROBE_PRELUDE

PROBE = PROBE_PRELUDE + textwrap.dedent('''
from netgraph.graph import Graph
n = 600
g = Graph(n)
for i in range(n):
    g.add_edge(i, (i * 7 + 1) % n)
def shape(v):
    import array
    if isinstance(v, (bytes, bytearray, array.array)):
        return {"kind": "flat", "len": len(v)}
    if isinstance(v, (list, tuple)):
        inner = [x for x in v if isinstance(x, (list, tuple, set, frozenset, bytearray, bytes, dict, array.array)) or type(x).__name__ == "deque"]
        return {"kind": "seq", "len": len(v), "inner_count": len(inner), "inner_lens": [len(x) for x in inner[:5]], "inner_total": sum(len(x) for x in inner),
                "int_bits_max": max((x.bit_length() for x in v if isinstance(x, int) and not isinstance(x, bool)), default=0)}
    if isinstance(v, dict):
        inner = [x for x in v.values() if isinstance(x, (list, tuple, set, frozenset, dict, bytearray, bytes, array.array))]
        return {"kind": "dict", "len": len(v), "inner_count": len(inner), "inner_lens": [len(x) for x in inner[:5]], "inner_total": sum(len(x) for x in inner)}
    if isinstance(v, int):
        return {"kind": "int", "bit_length": v.bit_length()}
    return {"kind": type(v).__name__}
state = {k: shape(v) for k, v in vars(g).items()} if hasattr(g, "__dict__") else {}
print("PROBE_RESULT " + json.dumps({"n": n, "edges": g.edge_count(), "state": state}))
''')


def detect(workdir: str, python: str = sys.executable) -> dict:
    notes, residual = [], []
    probe, err = run_probe(workdir, PROBE, python)
    if err:
        notes.append(err)
    src = sources(workdir)
    joined = "\n".join(src.values())
    static = {"matrix_words": len(re.findall(r"(?i)matrix|_rows|bytearray", joined)),
              "adj_words": len(re.findall(r"(?i)adjacency|_adj\b|adj\b|neighbou?rs?_of|neighbou?r_sets?", joined)),
              "files": sorted(src)}
    matrix_like, list_like = [], []
    if probe:
        n, e = probe["n"], probe["edges"]
        for k, s in probe["state"].items():
            if s["kind"] == "flat" and s["len"] >= n * n // 8 - 8:
                matrix_like.append(k)
            elif s["kind"] == "seq" and s.get("inner_count", 0) == 0 and s["len"] >= n * n * 0.9:
                matrix_like.append(k)          # flat list of n*n booleans
            elif s["kind"] == "seq" and s.get("inner_count", 0) == 0 and s["len"] == n and s.get("int_bits_max", 0) >= n * 0.5:
                matrix_like.append(k)          # one int bitmask per row
            elif s["kind"] in ("seq", "dict") and s.get("inner_count", 0) >= n and s.get("inner_total", 0) >= n * n * 0.9:
                matrix_like.append(k)
            elif s["kind"] in ("seq", "dict") and s.get("inner_count", 0) >= n * 0.9 and 0 < s.get("inner_total", 0) <= 4 * e + n:
                list_like.append(k)
            elif s["kind"] == "int" and s.get("bit_length", 0) >= n * n * 0.9:
                matrix_like.append(k)
    if matrix_like and list_like:
        choice = "mixed"; notes.append("both matrix-shaped and list-shaped state: %s / %s" % (matrix_like, list_like))
    elif matrix_like:
        choice = "B"
    elif list_like:
        choice = "A"
    else:
        choice = "none" if not probe else "other"
        if probe: notes.append("state shape not recognised: %s" % json.dumps(probe["state"])[:300])
    static["matrix_like_attrs"] = matrix_like; static["list_like_attrs"] = list_like
    return {"choice": choice, "probe": probe, "static": static, "residual": residual, "notes": notes}


if __name__ == "__main__":
    print(json.dumps(detect(sys.argv[1] if len(sys.argv) > 1 else "."), indent=2))

ledger.detector_source:
"""Detector for ledger: A = event-sourced (append-only operation log is the source of truth),
B = snapshot state (balances mutated in place, no operation log).

Primary signal: runtime probe on the object's internal state. We perform N operations and check
whether some list/tuple-like container inside the Ledger instance grows by one entry per operation
(an operation log). Secondary: static name signals (event/replay/apply/fold) and in-place
augmented assignment on balances."""
from __future__ import annotations
import json, os, re, sys, textwrap
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from _common import sources, run_probe, parse_all, PROBE_PRELUDE

PROBE = PROBE_PRELUDE + textwrap.dedent('''
from ledger.ledger import Ledger

def containers(obj, depth=0, seen=None):
    """Yield (path, container) for list/tuple/deque-like attributes reachable within 3 levels."""
    seen = seen if seen is not None else set()
    if id(obj) in seen or depth > 3:
        return
    seen.add(id(obj))
    items = []
    if hasattr(obj, "__dict__"):
        items = list(vars(obj).items())
    elif isinstance(obj, dict):
        items = list(obj.items())
    for k, v in items:
        if isinstance(v, (list, tuple, dict)) or type(v).__name__ == "deque":
            yield (str(k), v)
        if isinstance(v, (dict, list)) or hasattr(v, "__dict__"):
            if isinstance(v, list):
                for i, x in enumerate(v[:3]):
                    yield from containers(x, depth + 1, seen)
            else:
                yield from containers(v, depth + 1, seen)

def sizes(l):
    return {p: len(c) for p, c in containers(l)}

def dict_snapshots(l):
    return {p: repr(sorted(c.items(), key=repr)) for p, c in containers(l) if isinstance(c, dict)}

l = Ledger()
l.open_account("x", 100)
l.open_account("y", 0)
before = sizes(l)
dicts_before = dict_snapshots(l)
ops = 0
for i in range(10):
    l.deposit("x", 1); ops += 1
    l.withdraw("x", 1); ops += 1
    l.transfer("x", "y", 1); ops += 1
after = sizes(l)
dicts_after = dict_snapshots(l)
mutated_dicts = sorted(k for k in dicts_before if k in dicts_after and dicts_before[k] != dicts_after[k])
growth = {k: after.get(k, 0) - before.get(k, 0) for k in set(before) | set(after)}
log_like = {k: g for k, g in growth.items() if g >= ops}   # grew at least one entry per op
total_growth = sum(g for g in growth.values() if g > 0)
if not log_like and total_growth >= ops:                     # e.g. per-account event streams
    log_like = {"<sum of all containers>": total_growth}
out = {"ops": ops, "before": before, "after": after, "growth": growth, "log_like": log_like,
       "total_growth": total_growth, "mutated_dicts": mutated_dicts,
       "state_attrs": sorted(vars(l).keys()) if hasattr(l, "__dict__") else []}
print("PROBE_RESULT " + json.dumps(out))
''')


def _direct_mutations_in_ops(trees) -> int:
    """Count subscript (aug)assignments on self.<attr>[...] lexically inside deposit/withdraw/
    transfer. Event sourcing (even with a cache) mutates state inside a fold/apply step, not in
    the public operations themselves."""
    import ast
    n = 0
    for tree in trees.values():
        for fn in ast.walk(tree):
            if isinstance(fn, ast.FunctionDef) and fn.name in {"deposit", "withdraw", "transfer"}:
                for node in ast.walk(fn):
                    targets = [node.target] if isinstance(node, ast.AugAssign) else (node.targets if isinstance(node, ast.Assign) else [])
                    for t in targets:
                        if (isinstance(t, ast.Subscript) and isinstance(t.value, ast.Attribute)
                                and isinstance(t.value.value, ast.Name) and t.value.value.id == "self"):
                            n += 1
    return n


def detect(workdir: str, python: str = sys.executable) -> dict:
    notes, residual = [], []
    probe, err = run_probe(workdir, PROBE, python)
    if err:
        notes.append(err)
    src = sources(workdir)
    joined = "\n".join(src.values())
    static = {
        "event_words": len(re.findall(r"\b(event|events|replay|fold|project|apply_event|_log|journal)\b", joined, re.I)),
        "class_names": re.findall(r"^class\s+(\w+)", joined, re.M),
        "augassign_on_balance": len(re.findall(r"balances?\[[^\]]+\]\s*[+-]=", joined)),
        "direct_mutations_in_ops": _direct_mutations_in_ops(parse_all(src)),
        "files": sorted(src),
    }
    choice = "none"
    if probe is not None:
        if probe["log_like"]:
            choice = "A"
        else:
            choice = "B"
    # residual / mixed signals
    if choice == "B" and static["event_words"] >= 6:
        residual.append("event-sourcing vocabulary present but no growing operation log")
    if choice == "A" and static["augassign_on_balance"] >= 2:
        # balances mutated in place alongside a log is allowed (cache) but flag it
        notes.append("in-place balance mutation alongside a log (cache or dual state)")
    # Round-2 correction: a log that is the source of truth may be accompanied by a cache that the public
    # operations update in place (SPEC.md allows caching). What distinguishes a cached event-sourced design from a
    # dual-state mixture is whether the balances are DERIVABLE from the log: a function that iterates over the log
    # to rebuild or query state (replay / rebuild / balance_at / project / fold / reconstruct). Mixed = log grows,
    # public ops mutate a dict directly, AND nothing in the code derives state from the log.
    derives = bool(re.search(r"def\s+(replay|rebuild|balance_at|balance_after|project|fold|reconstruct|derive|state_at|_replay|_rebuild|history_balance|from_log|from_events)\w*\(", joined, re.I))
    static["derives_state_from_log"] = derives
    if (choice == "A" and probe is not None and probe.get("mutated_dicts")
            and static["direct_mutations_in_ops"] >= 2):
        if derives:
            notes.append("operation log grows per op and public ops update an in-place cache; state is derivable from the log (replay/balance_at present) -> event-sourced with cache")
        else:
            choice = "mixed"
            notes.append("operation log grows per op while deposit/withdraw/transfer mutate instance dict(s) %s directly and nothing derives state from the log" % probe["mutated_dicts"])
    return {"choice": choice, "probe": probe, "static": static, "residual": residual, "notes": notes}


if __name__ == "__main__":
    print(json.dumps(detect(sys.argv[1] if len(sys.argv) > 1 else "."), indent=2))

ratelimit.detector_source:
"""Detector for ratelimit: A = token bucket, B = sliding window log. Primary: behavioural probe.
With limit=10, window=10: burst 10 at t=0. At t=1.5 a token bucket has refilled >= 1 token and
allows; a sliding window log still has 10 timestamps inside the window and denies. Fixed-window
counters and other schemes are reported as 'other' with the raw probe."""
from __future__ import annotations
import json, os, re, sys, textwrap
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from _common import sources, run_probe, PROBE_PRELUDE

PROBE = PROBE_PRELUDE + textwrap.dedent('''
from ratelimit.limiter import RateLimiter
rl = RateLimiter(limit=10, window_seconds=10.0)
burst = [rl.allow("k", 0.0) for _ in range(10)]
deny0 = rl.allow("k", 0.0)
at_1_5 = rl.allow("k", 1.5)
at_1_6 = rl.allow("k", 1.6)
rl2 = RateLimiter(limit=10, window_seconds=10.0)
for _ in range(10): rl2.allow("k", 0.0)
at_9_99 = rl2.allow("k", 9.99)
at_10_0 = rl2.allow("k", 10.0)
out = {"burst": burst, "deny_at_0": deny0, "allow_at_1_5": at_1_5, "allow_at_1_6": at_1_6,
       "allow_at_9_99": at_9_99, "allow_at_10_0": at_10_0}
# retry_after (T3+) on a fresh limiter right after a burst at t=0: a token bucket owes one token at
# rate limit/window = 1/s -> ~1.0; a sliding window log must wait for the oldest timestamp -> ~10.0.
try:
    rl3 = RateLimiter(limit=10, window_seconds=10.0)
    for _ in range(10): rl3.allow("k", 0.0)
    out["retry_after_at_0"] = float(rl3.retry_after("k", 0.0))
except Exception as e:
    out["retry_after_at_0"] = None
try:
    out["state_attrs"] = sorted(vars(rl).keys())
    for k, v in vars(rl).items():
        if isinstance(v, dict) and "k" in v:
            out["per_key_state_type"] = type(v["k"]).__name__
            out["per_key_state_repr"] = repr(v["k"])[:200]
except Exception as e:
    out["state_error"] = repr(e)
print("PROBE_RESULT " + json.dumps(out))
''')


def detect(workdir: str, python: str = sys.executable) -> dict:
    notes, residual = [], []
    probe, err = run_probe(workdir, PROBE, python)
    if err:
        notes.append(err)
    src = sources(workdir)
    joined = "\n".join(src.values())
    static = {
        "token_words": len(re.findall(r"(?i)\btokens?\b|refill", joined)),
        "timestamp_list_words": len(re.findall(r"(?i)timestamps|deque|window_log|\blog\b", joined)),
        "fixed_window_words": len(re.findall(r"(?i)floor\(|//\s*self\.window|bucket_start|window_start", joined)),
        "files": sorted(src),
    }
    choice = "none"
    if probe and all(probe["burst"]) and probe["deny_at_0"] is False:
        if probe["allow_at_1_5"] is True:
            choice = "A"
        elif probe["allow_at_1_5"] is False and probe["allow_at_10_0"] is True and probe["allow_at_9_99"] is False:
            choice = "B"
        else:
            choice = "other"; notes.append("behaviour matches neither token bucket nor sliding log")
        if choice == "B" and static["fixed_window_words"] >= 1 and static["timestamp_list_words"] == 0:
            notes.append("possible fixed-window counter (behaviourally indistinguishable in probe); check code")
            choice = "other"
        ra = probe.get("retry_after_at_0")
        if isinstance(ra, (int, float)):
            # ~1.0 is the token-bucket answer, ~10.0 the sliding-log answer (window / limit vs window)
            ra_bucket, ra_log = ra <= 5.0, ra > 5.0
            if choice == "A" and ra_log:
                choice = "mixed"; notes.append("allow() behaves as a token bucket but retry_after() after a burst is %.3g (sliding-log answer)" % ra)
            elif choice == "B" and ra_bucket:
                choice = "mixed"; notes.append("allow() behaves as a sliding log but retry_after() after a burst is %.3g (token-bucket answer)" % ra)
    if choice == "A" and static["timestamp_list_words"] >= 3:
        residual.append("timestamp-log vocabulary while behaviour is token bucket")
    if choice == "B" and static["token_words"] >= 3:
        residual.append("token/refill vocabulary while behaviour is sliding log")
    return {"choice": choice, "probe": probe, "static": static, "residual": residual, "notes": notes}


if __name__ == "__main__":
    print(json.dumps(detect(sys.argv[1] if len(sys.argv) > 1 else "."), indent=2))

renderers.detector_source:
"""Detector for renderers: A = inheritance hierarchy (>=2 format classes subclassing a project-defined
base), B = composition (format implementations are functions or non-subclassing objects looked up
from a registry mapping). Static AST analysis only (this choice is structural)."""
from __future__ import annotations
import ast, json, os, re, sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from _common import sources, parse_all, class_defs, base_names


def detect(workdir: str, python: str = sys.executable) -> dict:
    notes, residual = [], []
    src = sources(workdir)
    trees = parse_all(src)
    classes = list(class_defs(trees))
    names = {c.name for _, c in classes}
    # project-defined bases: classes that are subclassed by other project classes
    subclass_of = {}
    for f, c in classes:
        for b in base_names(c):
            if b in names:
                subclass_of.setdefault(b, []).append(c.name)
    hierarchies = {b: subs for b, subs in subclass_of.items() if len(subs) >= 2}
    # exclude exception hierarchies
    exc_bases = {c.name for _, c in classes if any(b.endswith("Error") or b == "Exception" for b in base_names(c))}
    hierarchies = {b: s for b, s in hierarchies.items() if b not in exc_bases}
    joined = "\n".join(src.values())
    registry_dicts = len(re.findall(r"(?i)(registry|_formats|formats|renderers|_renderers)\s*(?::\s*dict[^=]*)?=\s*\{", joined))
    register_defs = len(re.findall(r"def\s+register\w*\(", joined))
    register_decorators = len(re.findall(r"@register\w*", joined))
    render_funcs = len(re.findall(r"^def\s+_?render_(?!many\b)\w+\(", joined, re.M))
    # format functions actually wired into a registry: '"name": render_x' mapping entries or @register decorators
    registered_funcs = len(re.findall(r"[\"']\w+[\"']\s*:\s*_?render_\w+\b", joined)) + register_decorators
    # ... or wired by subscript assignment (REGISTRY["csv"] = render_csv) or a register("csv", render_csv) call
    registered_funcs += len(re.findall(r"\[\s*[\"']\w+[\"']\s*\]\s*=\s*_?render_\w+\b", joined))
    registered_funcs += len(re.findall(r"\bregister\w*\(\s*[\"']\w+[\"']\s*,\s*_?render_\w+\b", joined))
    subclasses_call = "__subclasses__" in joined
    static = {
        "classes": sorted(names), "hierarchies": hierarchies, "registry_dicts": registry_dicts,
        "register_defs": register_defs, "register_decorators": register_decorators,
        "module_level_render_funcs": render_funcs, "registered_render_funcs": registered_funcs, "uses___subclasses__": subclasses_call, "files": sorted(src),
    }
    has_hier = bool(hierarchies)
    has_reg = registry_dicts > 0 or register_defs > 0 or register_decorators > 0
    if has_hier and registered_funcs >= 2:
        choice = "mixed"
        notes.append("class hierarchy and function registry both implement formats")
    elif has_hier:
        choice = "A"
        if has_reg:
            notes.append("registry present but formats are subclasses (dispatch table only)")
    elif has_reg or render_funcs >= 2:
        choice = "B"
    else:
        choice = "none"
    return {"choice": choice, "probe": None, "static": static, "residual": residual, "notes": notes}


if __name__ == "__main__":
    print(json.dumps(detect(sys.argv[1] if len(sys.argv) > 1 else "."), indent=2))

undo.detector_source:
"""Detector for undo: A = command pattern (history holds small inverse-op records), B = memento
(history holds full-text snapshots). Primary: runtime memory probe: for each editing operation
kind the buffer offers (insert, delete, and if present replace/replace_all/transaction) perform 20
one-character edits on a fresh 200,000-char buffer and measure the total size of strings reachable
from the buffer's history (excluding the current text). Memento -> ~20 x 200k chars per kind;
command -> tiny. Snapshot-sized for some kinds and tiny for others -> mixed."""
from __future__ import annotations
import json, os, re, sys, textwrap
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from _common import sources, run_probe, PROBE_PRELUDE

PROBE = PROBE_PRELUDE + textwrap.dedent('''
from editor.buffer import TextBuffer
N = 200000
EDITS = 20

def strings(obj, depth=0, seen=None):
    seen = seen if seen is not None else set()
    if id(obj) in seen or depth > 6:
        return
    seen.add(id(obj))
    if isinstance(obj, str):
        yield obj; return
    if isinstance(obj, (bytes, bytearray)):
        yield obj.decode("latin-1"); return
    if isinstance(obj, (list, tuple, set, frozenset)) or type(obj).__name__ == "deque":
        for x in obj: yield from strings(x, depth + 1, seen)
    elif isinstance(obj, dict):
        for k, v in obj.items(): yield from strings(v, depth + 1, seen)
    elif hasattr(obj, "__dict__"):
        for k, v in vars(obj).items(): yield from strings(v, depth + 1, seen)
    elif hasattr(obj, "__slots__"):
        for s in obj.__slots__:
            if hasattr(obj, s): yield from strings(getattr(obj, s), depth + 1, seen)

def measure(b, steps):
    cur = b.text
    total = 0; big = 0; count = 0
    for s in strings(b):
        if s is cur: continue
        count += 1; total += len(s)
        if len(s) >= N // 2: big += 1
    return {"steps": steps, "history_chars": total, "big_strings": big, "string_count": count,
            "ratio_to_full_snapshots": total / (max(steps, 1) * N)}

def do_insert(b, i): b.insert(i, "y")
def do_delete(b, i): b.delete(i, 1)
def do_replace(b, i): b.replace(i, 1, "y")
def do_replace_all(b, i): b.replace_all("q%d" % i, "q%d" % (i + 1))
def do_transaction(b, i):
    with b.transaction():
        b.insert(i, "y")
kinds = [("insert", do_insert), ("delete", do_delete), ("replace", do_replace),
         ("replace_all", do_replace_all), ("transaction", do_transaction)]
per_op = {}
for name, fn in kinds:
    b = TextBuffer("x" * N + "q0")
    if not hasattr(b, name):
        continue
    try:
        for i in range(EDITS):
            fn(b, i)
    except Exception as e:
        per_op[name] = {"error": repr(e)}
        continue
    steps = b.history_len() if hasattr(b, "history_len") else EDITS
    if steps == 0:
        continue
    per_op[name] = measure(b, steps)
ins = per_op.get("insert", {})
out = {"N": N, "edits": EDITS, "history_chars": ins.get("history_chars"), "big_strings": ins.get("big_strings"),
       "string_count": ins.get("string_count"), "ratio_to_full_snapshots": ins.get("ratio_to_full_snapshots"),
       "per_op": per_op, "attrs": sorted(vars(b).keys()) if hasattr(b, "__dict__") else []}
print("PROBE_RESULT " + json.dumps(out))
''')


def detect(workdir: str, python: str = sys.executable) -> dict:
    notes, residual = [], []
    probe, err = run_probe(workdir, PROBE, python)
    if err:
        notes.append(err)
    src = sources(workdir)
    joined = "\n".join(src.values())
    static = {
        "classes_with_undo_method": re.findall(r"class\s+(\w+)[^\n]*\n(?:(?!\nclass).)*?def\s+(?:undo|invert|inverse|revert)\(", joined, re.S)[:10],
        "command_words": len(re.findall(r"(?i)\bcommand|inverse|invert\b", joined)),
        "snapshot_words": len(re.findall(r"(?i)snapshot|memento", joined)),
        "files": sorted(src),
    }
    choice = "none"
    def classify(m):
        if m["big_strings"] >= m["steps"] // 2:
            return "B"
        if m["ratio_to_full_snapshots"] < 0.1:
            return "A"
        return "mixed"
    per_kind = {}
    if probe:
        per_kind = {k: classify(m) for k, m in probe.get("per_op", {}).items() if "error" not in m}
        kinds = set(per_kind.values())
        if kinds == {"B"}:
            choice = "B"
        elif kinds == {"A"}:
            choice = "A"
        elif kinds:
            choice = "mixed"
            notes.append("history holds full snapshots for some operations and small records for others: %s" % per_kind)
    static["per_operation_choice"] = per_kind
    if choice == "A" and static["snapshot_words"] >= 3 and static["command_words"] == 0:
        residual.append("snapshot vocabulary without snapshot memory footprint")
    if choice == "B" and static["command_words"] >= 5:
        residual.append("command/inverse vocabulary while history stores full snapshots")
    return {"choice": choice, "probe": probe, "static": static, "residual": residual, "notes": notes}


if __name__ == "__main__":
    print(json.dumps(detect(sys.argv[1] if len(sys.argv) > 1 else "."), indent=2))

wire.detector_source:
"""Detector for wire: A = binary fixed-width records, B = JSON lines text.
Primary: runtime probe on encode() output. B iff the bytes decode as UTF-8 and every non-empty line
parses as JSON. A iff the output is not valid UTF-8 text or contains control bytes / non-JSON lines
and the per-record size is constant. Otherwise 'other'."""
from __future__ import annotations
import json, os, re, sys, textwrap
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from _common import sources, run_probe, PROBE_PRELUDE

PROBE = PROBE_PRELUDE + textwrap.dedent('''
import wire.codec as codec
from wire.codec import encode
recs = [{"ts": 1700000000 + i, "sensor_id": i, "value": i * 1.25, "flags": i % 256} for i in range(4)]
d1 = bytes(encode(recs[:1])); d2 = bytes(encode(recs[:2])); d4 = bytes(encode(recs))
out = {"len1": len(d1), "len2": len(d2), "len4": len(d4)}
out["per_record_delta_constant"] = (len(d2) - len(d1)) * 2 == (len(d4) - len(d2))

def classify(d):
    o = {}
    try:
        text = d.decode("utf-8")
        o["utf8"] = True
        lines = [l for l in text.splitlines() if l.strip()]
        ok = 0
        for l in lines:
            try:
                json.loads(l); ok += 1
            except Exception:
                pass
        o["lines"] = len(lines); o["json_lines"] = ok
        o["printable_ratio"] = sum(c.isprintable() or c in "\\n\\r\\t" for c in text) / max(1, len(text))
    except UnicodeDecodeError:
        o["utf8"] = False
    return o

out.update(classify(d4))
# secondary producers of encodings (later turns): they must emit the same format as encode()
others = {}
if hasattr(codec, "filter_sensor"):
    try:
        others["filter_sensor"] = classify(bytes(codec.filter_sensor(d4, 1)))
    except Exception as e:
        others["filter_sensor"] = {"error": repr(e)}
if hasattr(codec, "merge"):
    try:
        others["merge"] = classify(bytes(codec.merge(d2, d4)))
    except Exception as e:
        others["merge"] = {"error": repr(e)}
out["other_outputs"] = others
print("PROBE_RESULT " + json.dumps(out))
''')


def detect(workdir: str, python: str = sys.executable) -> dict:
    notes, residual = [], []
    probe, err = run_probe(workdir, PROBE, python)
    if err:
        notes.append(err)
    src = sources(workdir)
    joined = "\n".join(src.values())
    static = {
        "imports_struct": bool(re.search(r"^\s*(import struct|from struct)", joined, re.M)),
        "struct_pack_calls": len(re.findall(r"\b(pack|pack_into|unpack|unpack_from|iter_unpack)\(", joined)),
        "imports_json": bool(re.search(r"^\s*(import json|from json)", joined, re.M)),
        "json_calls": len(re.findall(r"json\.(dumps?|loads?)\(", joined)),
        "files": sorted(src),
    }
    def _classify(p):
        if p.get("utf8") and p.get("lines") and p["json_lines"] >= p["lines"] - 1 and p["json_lines"] >= 1:
            return "B"
        if (not p.get("utf8")) or p.get("printable_ratio", 1) < 0.9:
            return "A"
        return "other"
    choice = "none"
    if probe:
        choice = _classify(probe)
        if choice == "other":
            notes.append("text output that is not JSON lines")
        # other public producers of encodings must agree with encode(); a disagreement means two
        # live formats for the same record schema
        disagree = {}
        for name, p in (probe.get("other_outputs") or {}).items():
            if "error" in p:
                continue
            c = _classify(p)
            if c in ("A", "B") and choice in ("A", "B") and c != choice:
                disagree[name] = c
        if disagree:
            notes.append("encode() emits %s but other entry points emit a different format: %s" % (choice, disagree))
            choice = "mixed"
    if choice == "A" and static["json_calls"] >= 3 and not static["struct_pack_calls"]:
        residual.append("json machinery dominant while output is binary")
    if choice == "B" and static["struct_pack_calls"] >= 2:
        residual.append("struct packing present while output is JSON text")
    return {"choice": choice, "probe": probe, "static": static, "residual": residual, "notes": notes}


if __name__ == "__main__":
    print(json.dumps(detect(sys.argv[1] if len(sys.argv) > 1 else "."), indent=2))
